Write the system of equations corresponding to:
\[
\left[\begin{array}{ccc|c}
1 & 0 & -3 & 4 \\
0 & 2 &  1 & -1 \\
5 & -1 & 0 & 2
\end{array}\right].
\]

\textbf{Solution:}
\begin{align*}
x_1 \phantom{{}+ 2x_2} - 3x_3 &= 4 \\
2x_2 + x_3 &= -1 \\
5x_1 - x_2 \phantom{{}+ 3x_3} &= 2
\end{align*}
\vspace{0.5cm}

\textbf{REF vs.\ RREF --- Quick Comparison:}

\medskip
\begin{center}
\begin{tabular}{@{}lcc@{}}
\toprule
\textbf{Property} & \textbf{REF} & \textbf{RREF} \\
\midrule
Zero rows at bottom           & \checkmark & \checkmark \\
Each pivot right of above     & \checkmark & \checkmark \\
Zeros below each pivot        & \checkmark & \checkmark \\
Each pivot $= 1$              & $\times$   & \checkmark \\
Zeros above each pivot        & $\times$   & \checkmark \\
\bottomrule
\end{tabular}
\end{center}

\bigskip
